def doy_dist(a,b):
    da=a.timetuple().tm_yday; db=b.timetuple().tm_yday
    x=abs(da-db); return min(x,365-x)
def pred_analog(train, dates, K=5, trend=True):
    ds=[d for d,y in train]; ys=[y for d,y in train]
    # linear trend per day
    slope=0
    if trend:
        xs=[(d-ds[0]).days for d in ds]; xm=sum(xs)/len(xs); ym=sum(ys)/len(ys)
        den=sum((x-xm)**2 for x in xs)
        slope=sum((x-xm)*(y-ym) for x,y in zip(xs,ys))/den if den else 0
    out=[]
    for td in dates:
        vals=[]
        for d,y in train:
            dd=doy_dist(td,d)
            if dd<=25:
                w=1/(dd+1)**2
                vals.append((w,y + slope*((td-d).days)))
        if len(vals)<K:
            vals=sorted([(1/(doy_dist(td,d)+1)**2, y+slope*((td-d).days)) for d,y in train], reverse=True)[:K]
        sw=sum(w for w,v in vals)
        out.append(sum(w*v for w,v in vals)/sw)
    return out
for K in [1,2,3,4,5,8,12,20]:
 for tr in [False,True]:
  errs=[]
