    cols=[np.ones_like(t)]
    # scaled polynomial trend
    x=(t-t.mean())/365.25
    if trend>=1: cols.append(x)
    if trend>=2: cols.append(x*x)
    if trend>=3: cols.append(x*x*x)
    for k in range(1,harmonics+1):
        ang=2*np.pi*k*t/365.25
        cols += [np.sin(ang), np.cos(ang)]
    return np.column_stack(cols)

