    start=min(dates)
    X=design(dates,start,harmonics,trend); yf=np.array(y,float)
    # ridge except intercept small
    A=X.T@X + ridge*np.eye(X.shape[1]); A[0,0]-=ridge
    beta=np.linalg.solve(A, X.T@yf)
    return design(fut_dates,start,harmonics,trend)@beta, beta

