    n=len(y)
    # rolling validation on last ~40, refit once on preceding? use blocked holdout last 51 to mimic
    cut=max(120,n-51)
    ph,_=fit_predict(dates[:cut], y[:cut], dates[cut:], h,tr,ridge)
    return float(np.mean(np.abs(ph-np.array(y[cut:]))))

