  for tr in [0,1,2]:
    for ridge in [0,0.01,0.1,1,10]:
      sc=[]
      for b in ['VH','VV']:
        dates=[x[0] for x in hist[b]]; y=[x[2] for x in hist[b]]
        sc.append(cv_score(dates,y,h,tr,ridge))
