from collections import defaultdict

def date_to_year_float(d):
    start=dt.date(d.year,1,1); end=dt.date(d.year+1,1,1)
    return d.year + (d-start).days/((end-start).days)

def features(d):
    yf=date_to_year_float(d)
    x=yf-2020.0
    doy=(d-dt.date(d.year,1,1)).days
    period=(dt.date(d.year+1,1,1)-dt.date(d.year,1,1)).days
    theta=2*math.pi*doy/period
    fs=[1.0, x]
    for k in range(1,5):
        fs += [math.sin(k*theta), math.cos(k*theta)]
    return fs

def solve(A,b):
    n=len(b)
    M=[A[i][:]+[b[i]] for i in range(n)]
    for col in range(n):
        piv=max(range(col,n), key=lambda r: abs(M[r][col]))
        if abs(M[piv][col])<1e-12: continue
        M[col],M[piv]=M[piv],M[col]
        div=M[col][col]
        for j in range(col,n+1): M[col][j]/=div
        for r in range(n):
            if r==col: continue
            fac=M[r][col]
            if fac:
                for j in range(col,n+1): M[r][j]-=fac*M[col][j]
    return [M[i][n] for i in range(n)]

def fit_predict(obs, targets, ridge=0.05):
