        for i in range(p):
            Xty[i]+=f[i]*y
            for j in range(p):
                XtX[i][j]+=f[i]*f[j]
    for i in range(p):
        XtX[i][i]+=ridge if i>0 else 1e-8
    beta=solve(XtX,Xty)
    return {pid: sum(b*x for b,x in zip(beta,features(d))) for pid,d in targets}

